536	/**
537	 * Place an order: validate, charge the wallet (unless a free admin grant),
538	 * create the Server + PROVISION job. Returns the new server id. Does NOT
539	 * redirect. Callers must ensure funds exist (or pass free) — this still
540	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
541	 *
542	 * `sold` overrides the recomputed price with the one the order was actually SOLD
543	 * at — the card-paid path passes the figure stamped on the Checkout session
544	 * BEFORE the card was charged, so the confirm redirect settles the price the
545	 * customer consented to instead of re-pricing against whatever promo is running
546	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
547	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
548	 * quote, which it computed moments ago in the same request. See OrderPrice.
549	 */
550	/**
551	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
552	 * any failure so nothing partial survives. Kept separate from the order tx so a
553	 * wallet order can surface the failure before any money moves, and a card order
554	 * (already paid) can swallow it without stranding the paid provision.
555	 *
556	 * Guards, all enforced here: first-time-only (no prior paid server), the
557	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
558	 * (the two @@unique constraints on CouponRedemption).
559	 */
560	export async function claimOrderCoupon(opts: {
561	  couponId: string;
562	  maxRedemptions: number | null;
563	  firstTimeOnly: boolean;
564	  userId: string;
565	  ipHash: string | null;
566	  amountCents: number;
567	}): Promise<void> {
568	  await db.$transaction(async (tx) => {
569	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
570	    // not stand between them and this coupon on a fresh (wallet) order — and its global
571	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
572	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
573	    if (opts.firstTimeOnly) {
574	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
575	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
576	    }
577	    // Atomic conditional increment — the only thing between the last free slot and
578	    // an over-redemption when two orders race for it.
579	    const claim = await tx.coupon.updateMany({
580	      where:
581	        opts.maxRedemptions === null
582	          ? { id: opts.couponId, active: true }
583	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
584	      data: { timesRedeemed: { increment: 1 } },
585	    });
586	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
587	    try {
588	      await tx.couponRedemption.create({
589	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
590	      });
591	    } catch {
592	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
593	      // this person. Throwing rolls back the increment above with it.
594	      throw new OrderError("You’ve already used this code.");
595	    }
596	  });
597	}
598	
599	/**
600	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
601	 *
602	 * The card leg discounts `cardCents` up front and only settles the redemption
603	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
604	 * paid provision is never stranded. Without this pre-check, a customer who has
605	 * already used a one-per-person code (or isn't first-time) still gets the
606	 * discounted card charge and the swallow hides it. So before we send them to
607	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
608	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
609	 * (a race could still lose the atomic claim at settle time — that path stays
610	 * swallowed by design), but it closes the everyday bypass.
611	 */
612	export async function orderCouponClaimable(opts: {
613	  couponId: string;
614	  firstTimeOnly: boolean;
615	  maxRedemptions: number | null;
616	  userId: string;
617	  ipHash: string | null;
618	}): Promise<{ ok: true } | { ok: false; error: string }> {
619	  if (opts.firstTimeOnly) {
620	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
621	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
622	  }
623	  const byUser = await db.couponRedemption.findUnique({
624	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
625	  });
626	  if (byUser) return { ok: false, error: "You’ve already used this code." };
627	  if (opts.ipHash) {
628	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
629	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
630	  }
631	  if (opts.maxRedemptions !== null) {
632	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
633	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
634	  }
635	  return { ok: true };
636	}
