638	export async function placeOrder(
639	  user: User,
640	  intent: OrderIntent,
641	  sold?: OrderPrice | null,
642	  opts?: {
643	    ipHash?: string | null;
644	    campaign?: string;
645	    promoReservationToken?: string | null;
646	    couponReservationToken?: string | null;
647	  },
648	): Promise<string> {
649	  const quote = await orderQuote(intent);
650	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents, ipCents } = quote;
651	  // Everything below bills off THESE three, never off `quote.chargeCents` /
652	  // `promo` directly: when a sold price is present it is the whole truth about
653	  // what this order costs and what rate it was sold at.
654	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
655	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
656	  const promoName = sold?.promoName || promo.name;
657	
658	  // Managed first-month-free — how this order settles the credit depends on the path:
659	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
660	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
661	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
662	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
663	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
