399	/**
400	 * Has real money actually reached Nxeon for this user?
401	 *
402	 * The evidence is a wallet credit carrying a Stripe identifier: `stripeSessionId`
403	 * (Checkout) or `stripePaymentIntentId` (an off-session renewal charge). Both are
404	 * written only by lib/stripe.ts / lib/stripe-cards.ts after Stripe confirmed a
405	 * payment, and both are UNIQUE, so neither can be forged or replayed by a caller.
406	 *
407	 * DELIBERATELY NOT accepted as proof, each for a reason:
408	 *
409	 *   - a positive `WalletTransaction` on its own. Signup credit, admin credit,
410	 *     gift credit and the referral bonus itself are all positive rows. Accepting
411	 *     them would let free credit bootstrap more free credit.
412	 *   - a negative (spend) row. Spending proves only that a balance existed, not
413	 *     that anyone paid for it — an account funded by signup credit could buy the
414	 *     cheapest product and claim the reward, which is the same attack one step
415	 *     further along.
416	 *   - the demo gateway in `topUp`. It mints balance with no payment; it is
417	 *     refused outright when NODE_ENV is production or Stripe is configured, so it
418	 *     only ever runs on a developer's machine. Exercising the referral path
419	 *     locally needs Stripe test mode — the alternative is a rule that says "in
420	 *     some builds, unpaid counts as paid", and that is how this bug happens
421	 *     again.
422	 *
423	 * Fails CLOSED: a user whose wallet was funded by someone else's payment (a gift)
424	 * does not qualify, and gets no reward. Refusing a legitimate $5 is recoverable
425	 * by hand; paying an illegitimate $10 per fake account is not.
426	 */
427	async function hasPaidAction(userId: string): Promise<boolean> {
428	  const paid = await db.walletTransaction.count({
429	    where: {
430	      userId,
431	      OR: [{ stripeSessionId: { not: null } }, { stripePaymentIntentId: { not: null } }],
432	    },
433	  });
434	  return paid > 0;
435	}
