437	/**
438	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
439	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
440	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
441	 * Callable from `topUp` in lib/actions.ts, from `placeOrder` in lib/order.ts and
442	 * from `creditCheckoutSession` in lib/stripe.ts — after a paid action.
443	 *
444	 * ── WHY "AFTER A PAID ACTION" IS CHECKED HERE, NOT TRUSTED ───────────────────
445	 *
446	 * This function is an exported member of a `"use server"` module, so it is a
447	 * network endpoint: a stranger can POST to it. `assertInternalGrowthCaller`
448	 * closes the "credit someone ELSE" hole, and its rule is "if there is a session,
449	 * it must be the account being credited".
450	 *
451	 * That rule does not close, and cannot close, the hole that matters most, because
452	 * the attacker's account IS the account being credited. Signed in as themselves,
453	 * they satisfy that guard by construction — it is the attacker's own case.
454	 *
455	 * The precondition that made this safe — "only call me after money changed
456	 * hands" — lived ENTIRELY in the three callers. A caller-held precondition is no
457	 * precondition at all for a function anyone can call directly. With
458	 * `referral_reward_cents` defaulting to 500 and paid to BOTH sides, each fake
459	 * signup that reached this endpoint minted ~$10 of spendable wallet balance at
460	 * zero spend, repeatable per account and limited only by how fast accounts can
461	 * be created.
462	 *
463	 * So the precondition is enforced here now, against the ledger, and no caller is
464	 * trusted to have checked it.
465	 */
466	export async function maybeRewardReferral(userId: string): Promise<boolean> {
467	  await assertInternalGrowthCaller(userId);
468	  // Feature flag: the referral program can be switched off platform-wide.
469	  if (!(await getSettingBool("feature_referrals", true))) return false;
470	
471	  // THE PRECONDITION. Checked before anything is read about the referral and
472	  // long before anything is written, so the endpoint is inert for an account
473	  // that has never paid — which is every account an attacker can create.
474	  if (!(await hasPaidAction(userId))) return false;
475	
476	  // Settings → Growth writes `referral_reward_cents` and displays it, but NOTHING
477	  // read it — the payout used the env-backed `referralRewardCents()` instead, so an
478	  // operator changing the reward saw "Saved." and the platform kept paying the old
479	  // amount. Same shape as the domain markup showing 0% while charging 25%, and the
480	  // auto-suspend switch that silenced nothing.
481	  //
482	  // Clamped, and the ceiling matters more here than anywhere else: this reward is
483	  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
484	  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
485	  // already absurd; anything beyond it is certainly a typo.
486	  const reward = Math.min(
487	    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
488	    100_000
489	  );
490	  if (reward <= 0) return false;
491	
492	  const user = await db.user.findUnique({ where: { id: userId } });
493	  if (!user || !user.referredById || user.referralRewardedAt) return false;
494	  const referrerId = user.referredById;
495	
496	  // Atomically claim the reward; if another concurrent action already did, bail.
497	  const claim = await db.user.updateMany({
498	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
499	    data: { referralRewardedAt: new Date() },
500	  });
501	  if (claim.count === 0) return false;
502	
503	  await db.$transaction([
504	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
505	    db.walletTransaction.create({
506	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
507	    }),
508	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
509	    db.walletTransaction.create({
510	      data: {
511	        userId: referrerId,
512	        amountCents: reward,
513	        description: "Referral bonus — you referred a friend",
514	      },
515	    }),
516	  ]);
517	
518	  // Best-effort in-app notifications, filtered through the notification policy.
519	  //
520	  // `referral_bonus` is ACCOUNT tier, so the in-app bell is never suppressed —
521	  // these rows are the customer's record of money that entered their wallet, and
522	  // hiding a credit would be the same "it silently disappeared" failure the
523	  // preferences exist to cure. The gate is here anyway so the tier in
524	  // `lib/prefs.ts` stays the single decider: if this kind is ever reclassified,
525	  // the filter starts biting without anyone having to remember this call site.
526	  try {
527	    const rows = [
528	      {
529	        userId,
530	        title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
531	        href: "/dashboard/billing",
532	      },
533	      {
534	        userId: referrerId,
535	        title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
536	        href: "/dashboard/refer",
537	      },
538	    ];
539	    const allowed: typeof rows = [];
540	    for (const row of rows) {
541	      if (await mayDeliverTo(row.userId, "referral_bonus", "inapp")) allowed.push(row);
542	    }
543	    if (allowed.length > 0) await db.notification.createMany({ data: allowed });
544	  } catch {
545	    /* best-effort */
546	  }
547	  return true;
548	}
