58	/* ------------------------------------------------------------------ *
59	 * CARD AUTO-CHARGE + DUNNING
60	 *
61	 * A renewal applies wallet credit FIRST and auto-charges the saved card for the
62	 * remainder — the same split `lib/wallet-split.ts` gives checkout, so a renewal
63	 * behaves exactly like a purchase and prepaid/referral/refund credit gets drained
64	 * instead of accumulating as a liability.
65	 *
66	 * When the card fails the customer is NOT suspended. The card is retried on days
67	 * 1, 3 and 5 past expiry, each with its own email, and only once every attempt is
68	 * spent — plus one clear day after the final notice — does the server pause. The
69	 * old behaviour sent a customer with a perfectly good card straight to SUSPENDED
70	 * the moment their wallet emptied, and told them about it with nothing but a bell
71	 * icon in a portal they had stopped visiting.
72	 * ------------------------------------------------------------------ */
73	
74	/**
75	 * Days past expiry for retry N (1-based): 1, 3, 5 …
76	 *
77	 * Derived from DUNNING_RETRY_ATTEMPTS — the same constant `emails.paymentRetryFailed`
78	 * uses to tell the customer how many attempts remain — so the schedule the worker
79	 * runs and the number in the email can never drift apart.
80	 */
81	const retryDayFor = (retry: number) => 2 * retry - 1;
82	/** Days past expiry of the LAST automatic retry. */
83	const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
84	/** One clear day between the final-notice email and the suspension it warns about. */
85	const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;
86	/** `Server.dunningStage` once the attempt on expiry day AND every retry have failed. */
87	const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;
88	/**
89	 * Never schedule a retry sooner than this. The sweep runs every 10 minutes, so a
90	 * worker that was down for a week would otherwise burn every retry — and every
91	 * email — in the space of one afternoon.
92	 */
93	const MIN_RETRY_GAP_MS = 20 * 3600_000;
94	/** How soon to re-try after an error that was OUR side, not the customer's. */
95	const TRANSIENT_RETRY_MS = 60 * 60_000;
96	/**
97	 * Hard cap on how far a late-starting or error-delayed sequence may push a
98	 * suspension past its calendar date. `suspendDueAt` waits for a retry we have
99	 * PROMISED the customer, and a Stripe outage reschedules that promise hourly
100	 * forever — without this cap "never suspend mid-sequence" would quietly become
101	 * "never suspend at all".
102	 */
103	const SUSPEND_SLIP_CAP_DAYS = 4;
104	/** Warn about a saved card this many days before it expires. */
105	const CARD_EXPIRY_WARN_DAYS = 30;
106	/** Re-nudge about a still-unreplaced expiring/expired card at most this often. */
107	const CARD_EXPIRY_RENUDGE_DAYS = 60;
108	/** Ledger description prefix that identifies an automatic wallet top-up. */
109	const AUTO_RECHARGE_DESC = "Automatic wallet top-up";
110	/** Mirrors the floor `saveAutoRecharge` enforces on the customer's own input. */
111	const AUTO_RECHARGE_MIN_CENTS = 500;
112	
113	/**
114	 * Dunning windows, all measured in DAYS PAST EXPIRY.
115	 *
116	 * Settings → Billing is the source of truth. Those three fields and the
117	 * "Auto-suspend overdue accounts" toggle used to be written to the Setting table and
118	 * read by NOTHING: the worker used env vars that were never set, so an operator who
119	 * turned suspensions off during an incident saw "Saved." and then watched the sweep
120	 * knock customer VMs offline ten minutes later.
121	 *
122	 * The legacy env vars remain as fallbacks, converted onto the days-past-expiry clock
123	 * so an operator who had set them keeps the behaviour they configured
124	 * (NXEON_TERMINATE_DAYS counted forward from the END of grace, and
125	 * NXEON_WARN_BEFORE_TERMINATE_DAYS counted backwards from termination).
126	 */
127	type DunningConfig = {
128	  /** Days past expiry before an account with no card in play is suspended. */
129	  graceDays: number;
130	  /** Days past expiry when the "will be deleted" warning goes out. */
131	  warnDays: number;
132	  /** Days past expiry when an unpaid SUSPENDED server is destroyed. */
133	  terminateDays: number;
134	  /** Admin kill switch: when false the sweep suspends and terminates nothing. */
135	  autoSuspend: boolean;
136	};
137	
138	const ENV_GRACE_DAYS = Number(process.env.NXEON_GRACE_DAYS ?? 3);
139	const ENV_TERMINATE_DAYS = process.env.NXEON_TERMINATE_DAYS
140	  ? ENV_GRACE_DAYS + Number(process.env.NXEON_TERMINATE_DAYS)
141	  : 14;
142	const ENV_WARN_DAYS = process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS
143	  ? ENV_TERMINATE_DAYS - Number(process.env.NXEON_WARN_BEFORE_TERMINATE_DAYS)
144	  : 7;
145	
146	async function dunningConfig(): Promise<DunningConfig> {
147	  const graceDays = Math.max(0, await getSettingInt("dunning_grace_days", ENV_GRACE_DAYS));
148	  let terminateDays = await getSettingInt("dunning_terminate_days", ENV_TERMINATE_DAYS);
149	  let warnDays = await getSettingInt("dunning_warn_days", ENV_WARN_DAYS);
150	  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
151	
152	  // Clamp. These are free-text number fields in an admin panel and the action they
153	  // gate is irreversible — a typo (or a 0) must never be able to destroy a VM on the
154	  // same day it is suspended, or before the dunning sequence has even finished. The
155	  // floor includes the slip cap because a card sequence that started late can push
156	  // the suspension itself out to CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS, and
157	  // termination must always land AFTER the suspension it follows.
158	  const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
159	  terminateDays = Math.max(terminateDays, latestSuspendDay + 1);
160	  warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);
161	  return { graceDays, warnDays, terminateDays, autoSuspend };
162	}
