385	/**
386	 * One expired server: renew it from wallet + card, or move it along the dunning
387	 * sequence, or suspend it once every promised attempt is spent.
388	 */
389	async function renewDueServer(
390	  server: DueServer,
391	  ctx: {
392	    now: Date;
393	    cfg: DunningConfig;
394	    prices: { ipMonthlyCents: number; extraDiskPerGbCents: number; backupPlusCents: number; annualDiscountPct: number };
395	    taxParams: { sellerCountry: string; fallbackPercent: number };
396	    paypalFallbackEnabled: boolean;
397	  },
398	) {
399	  const { now, cfg, taxParams, paypalFallbackEnabled } = ctx;
400	  // Resolve the owner's VAT/GST from their billing country (Finding 1) and fold it
401	  // into the renewal price so the wallet debit, any card leg and the invoice all
402	  // agree. Default rate 0 (no country on file) leaves this identical to before.
403	  const taxCtx = resolveCountryTaxRate({
404	    country: server.user.billingCountry ?? null,
405	    vatId: server.user.vatId ?? null,
406	    sellerCountry: taxParams.sellerCountry,
407	    fallbackPercent: taxParams.fallbackPercent,
408	  });
409	  const prices = { ...ctx.prices, taxRatePercent: taxCtx.ratePercent };
410	  const charge = renewalCharge(server, prices);
411	  const renewCents = charge.totalCents;
412	  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
413	  const newExpiry = addMonths(base, charge.months);
414	
415	  await clearStaleDunning(server);
416	
417	  let renewed = false;
418	  if (server.autoRenew) {
419	    // `server.user.balanceCents` came from a snapshot taken before this loop and
420	    // is stale as soon as the first renewal in this pass debits a wallet, so the
421	    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
422	    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
423	    // concurrent renewNow()/second pass charging the same period twice.
424	    const fresh = await db.user.findUnique({
425	      where: { id: server.userId },
426	      select: { balanceCents: true },
427	    });
428	    const split = walletSplit({
429	      dueCents: renewCents,
430	      balanceCents: fresh?.balanceCents ?? 0,
431	      useWallet: true,
432	    });
433	    const cardInPlay = hasChargeableCard(server.user);
434	    const paypalInPlay = !cardInPlay && paypalFallbackEnabled && hasChargeablePayPal(server.user);
435	
436	    if (split.cardCents === 0) {
437	      // Wallet covers the whole renewal — no card involved, no Stripe call.
438	      const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry: taxCtx.country });
439	      renewed = outcome !== "insufficient";
440	      if (outcome === "renewed") {
441	        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
442	      }
443	    } else if (cardInPlay) {
444	      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
445	      // would burn all three retries — and send all three emails — within half an
446	      // hour of the first decline.
447	      //
448	      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
449	      // two things. `retryDunningNow` (fired when a customer saves a new card
450	      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
451	      // would suspend a customer whose brand-new card we never once tried. And the
452	      // exhausted stage's schedule points at the suspension day itself, so every
453	      // server gets one final, silent try at the card in the same pass that pauses it.
454	      const dueForRetry = server.dunningNextAt
455	        ? now >= server.dunningNextAt
456	        : server.dunningStage < DUNNING_EXHAUSTED;
457	      if (dueForRetry) {
458	        renewed = await attemptCardRenewal({
459	          server,
460	          charge,
461	          cardCents: split.cardCents,
462	          newExpiry,
463	          now,
464	          cfg,
465	          taxCountry: taxCtx.country,
466	        });
467	      }
468	    } else if (paypalInPlay) {
469	      // Same scheduled-retry gate as the card path above — a PayPal-funded
470	      // customer gets the exact same dunning cadence, not an immediate try
471	      // every 10-minute sweep tick.
472	      const dueForRetry = server.dunningNextAt
473	        ? now >= server.dunningNextAt
474	        : server.dunningStage < DUNNING_EXHAUSTED;
475	      if (dueForRetry) {
476	        renewed = await attemptPayPalRenewal({
477	          server,
478	          charge,
479	          cardCents: split.cardCents,
480	          newExpiry,
481	          now,
482	          cfg,
483	          taxCountry: taxCtx.country,
484	        });
485	      }
486	    } else {
487	      console.log(
488	        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
489	      );
490	    }
491	  }
492	
493	  if (renewed) {
494	    // nothing further this pass
495	  } else {
496	    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
497	    if (suspendAt && now >= suspendAt) {
498	      await suspendUnpaid(server, cfg);
499	    }
500	  }
501	}
