503	/**
504	 * Drop dunning state that belongs to a period we are no longer collecting for.
505	 *
506	 * `renewNow` (lib/actions.ts) advances `expiresAt` without touching the dunning
507	 * columns, so a customer who paid by hand halfway through a sequence carries a
508	 * stale `dunningStage` into the NEXT period — and the first decline of that fresh
509	 * period would arrive as "payment retry 2 declined, 1 attempt remaining", on a
510	 * compressed schedule, for a period they had never failed once.
511	 *
512	 * Every schedule this file writes lands at or after the expiry it was computed
513	 * from, so a `dunningNextAt` that predates the CURRENT `expiresAt` can only have
514	 * been written for an older, already-settled period.
515	 */
516	async function clearStaleDunning(server: DueServer): Promise<void> {
517	  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
518	  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
519	  if (belongsToThisPeriod) return;
520	
521	  await db.server.update({
522	    where: { id: server.id },
523	    data: { dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
524	  });
525	  // Keep the in-memory row honest: the rest of this pass reads these fields to
526	  // decide whether to charge, which email to send and when to suspend.
527	  server.dunningStage = 0;
528	  server.dunningNextAt = null;
529	  server.dunningPayUrl = null;
530	}
