532	/* ------------------------------------------------------------------ *
533	 * Renewal commit (wallet) + card auto-charge
534	 * ------------------------------------------------------------------ */
535	
536	/**
537	 * Advance the term and take the money from the wallet, atomically.
538	 *
539	 * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
540	 * by a top-up, a referral credit or the saved card moments ago. One money path
541	 * means a partial failure can never half-apply a renewal: either the period
542	 * advances AND the wallet is debited AND the invoice exists, or none of it happened.
543	 *
544	 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
545	 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
546	 * the first `updateMany` to match it writes, and every loser rolls back its debit
547	 * and its invoice with the transaction. Zero rows matched = someone else already
548	 * renewed this period, which is a success for us, not an error.
549	 */
550	async function commitRenewal(opts: {
551	  server: DueServer;
552	  charge: RenewalCharge;
553	  newExpiry: Date;
554	  /** Destination country the VAT was charged for (Finding 1); recorded on the invoice. */
555	  taxCountry?: string;
556	}): Promise<"renewed" | "insufficient" | "already"> {
557	  const { server, charge, newExpiry, taxCountry } = opts;
558	  // Captured from the in-tx invoice.create so the renewal invoice can be emailed
559	  // (with its PDF) only after the CAS-guarded tx commits — a rolled-back / already-
560	  // renewed sweep leaves this null and emails nothing.
561	  let renewedInvoice: { id: string; number: number; amountCents: number } | null = null;
562	  const renewCents = charge.totalCents;
563	  const { netCents, taxCents, taxRatePercent, extraDiskCents, extraDiskMonthlyCents, backupCents, backupMonthlyCents } = charge;
564	  const periodStart = server.expiresAt!;
565	
566	  // `renewalCharge` bills `vpsTermPriceCents` (or a game plan's flat price) with NO
567	  // seasonal promo — renewals never get the intro discount, exactly as
568	  // lib/promotions.ts promises. So the months this renewal adds were sold at 0% off
569	  // and the term's stored rate basis must say so, or a later downgrade credits them
570	  // at a promo rate nobody was ever charged. Blended rather than overwritten for the
571	  // same reason as renewNow: this sweep only fires on already-expired servers (so
572	  // the blend is 0 in practice), but the shared helper means the two renewal paths
573	  // cannot express different rules for the same event.
574	  const renewedPercent = prorateBlendPercent({
575	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
576	    currentMonths: remainingMonths(server.expiresAt, Date.now()),
577	    addedPercent: 0,
578	    addedMonths: charge.months,
579	  });
580	
581	  try {
582	    await db.$transaction(async (tx) => {
583	      const advanced = await tx.server.updateMany({
584	        where: { id: server.id, expiresAt: server.expiresAt },
585	        data: {
586	          expiresAt: newExpiry,
587	          termPromoPercent: renewedPercent,
588	          // The period is paid, so the collection state that belonged to it dies
589	          // with it. Leaving a stage behind would hand the NEXT period a
590	          // half-spent retry budget and the wrong dunning email.
591	          dunningStage: 0,
592	          dunningNextAt: null,
593	          dunningPayUrl: null,
594	        },
595	      });
596	      if (advanced.count === 0) throw new AlreadyRenewedError();
597	      await debitWallet(tx, server.userId, renewCents);
598	      await tx.walletTransaction.create({
599	        data: {
600	          userId: server.userId,
601	          amountCents: -renewCents,
602	          description: `Renewal: ${charge.label} (${server.hostname})`,
603	        },
604	      });
605	      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
606	      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
607	      // never producing a second invoice for the same period.
608	      const renewalInvoice = await tx.invoice.create({
609	        data: invoiceCreateData({
610	          userId: server.userId,
611	          description: `Renewal: ${charge.label} (${server.hostname})`,
612	          status: "PAID",
613	          // Snapshot the card on file at charge time (null-safe for wallet-only users).
614	          paidBrand: server.user.cardBrand ?? null,
615	          paidLast4: server.user.cardLast4 ?? null,
616	          // VAT recorded separately; the line items below sum to the NET (netCents).
617	          taxCents,
618	          taxRatePercent,
619	          taxCountry: taxCountry ?? null,
620	          period: { start: periodStart, end: newExpiry },
621	          // Extra disk gets its OWN line so the customer sees exactly what the
622	          // permanent storage costs each cycle; the lines sum back to netCents.
623	          lineItems: [
624	            {
625	              description: `${charge.label} — ${server.hostname}`,
626	              qty: 1,
627	              unitCents: netCents - extraDiskCents - backupCents,
628	              amountCents: netCents - extraDiskCents - backupCents,
629	            },
630	            ...(extraDiskCents > 0
631	              ? [
632	                  {
633	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
634	                    qty: 1,
635	                    unitCents: extraDiskCents,
636	                    amountCents: extraDiskCents,
637	                  },
638	                ]
639	              : []),
640	            // Paid backup retention (Plus) gets its own line, mirroring extra disk,
641	            // so the customer sees exactly what the retention upsell costs each cycle.
642	            ...(backupCents > 0
643	              ? [
644	                  {
645	                    description: `Plus backups (keep 7) — ${server.hostname} ($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
646	                    qty: 1,
647	                    unitCents: backupCents,
648	                    amountCents: backupCents,
649	                  },
650	                ]
651	              : []),
652	          ],
653	        }),
654	      });
655	      renewedInvoice = {
656	        id: renewalInvoice.id,
657	        number: renewalInvoice.number,
658	        amountCents: renewalInvoice.amountCents,
659	      };
660	      await tx.auditLog.create({
661	        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
662	      });
663	      // First-month-free conversion: this is the server's SECOND term. Flip the
664	      // redemption anchored to it to renewed (idempotent, same tx as the money).
665	      await markPromoRenewed(tx, server.id);
666	    });
667	  } catch (e) {
668	    if (e instanceof InsufficientBalanceError) {
669	      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
670	      return "insufficient";
671	    }
672	    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
673	    throw e;
674	  }
675	
676	  // The period is settled. Any 3-D Secure challenge still hanging off it is a
677	  // loaded gun: anything that later confirms that intent takes a SECOND payment
678	  // for a period we have already been paid for. Only worth a Stripe round-trip
679	  // when this server was actually mid-dunning.
680	  if (server.dunningStage > 0 || server.dunningPayUrl) {
681	    await cancelPendingChargeForMarker(
682	      server.user.stripeCustomerId,
683	      renewalChargeMarker(server.id, periodStart),
684	    );
685	  }
686	
687	  // A settled period ends the reminder cycle: clear the card-less renewal reminder
688	  // so the NEXT approach-to-expiry can remind once more. Guarded on the in-memory
689	  // flag so the wallet-only majority skip the write, and best-effort so this
690	  // housekeeping can never unwind a renewal that already committed.
691	  if (reminderSentAt(server)) {
692	    await reminderServer()
693	      .update({ where: { id: server.id }, data: { renewalReminderSentAt: null } })
694	      .catch(() => {});
695	  }
696	
697	  // Email the renewal INVOICE with its PDF attached. Best-effort and post-commit —
698	  // the term is already settled, so a mail failure must never unwind a renewal.
699	  // Fires exactly once per successful renewal because this is the single "renewed"
700	  // exit of the CAS-guarded commit, reached by BOTH the wallet-only path and the
701	  // card path. Deliberately `invoiceNew` (subject "Invoice #… — $… due"), NOT
702	  // `receipt`: a card renewal already gets a distinct card-charge paymentReceipt
703	  // above, and a second "Payment received — $…" would duplicate it — this is the
704	  // invoice document instead. `kind:"invoice"` is ACCOUNT-tier (suppressible), and
705	  // the `invoice_new` template is in the mailer's attach set, so the PDF attaches.
706	  // Read via the declared union — the value is assigned inside the $transaction
707	  // callback, which TS control-flow analysis does not track, so a direct read would
708	  // narrow to `null`.
709	  const invForEmail = renewedInvoice as { id: string; number: number; amountCents: number } | null;
710	  if (invForEmail) {
711	    try {
712	      const branding = await invoiceBranding();
713	      await mail(
714	        server.user.email,
715	        server.userId,
716	        emails.invoiceNew(
717	          {
718	            invoiceNumber: formatInvoiceNumber(invForEmail.number, branding.numberPrefix),
719	            amount: fmtUsd(invForEmail.amountCents),
720	            dueDate: fmtDay(new Date()),
721	            description: `${charge.label} — ${server.hostname}`,
722	          },
723	          true, // the itemised PDF is attached (invoiceId passed below)
724	        ),
725	        "invoice",
726	        invForEmail.id,
727	      );
728	    } catch (e) {
729	      console.error("[billing] renewal invoice email failed", e);
730	    }
731	  }
732	  return "renewed";
733	}
