735	/**
736	 * Charge the saved card for the wallet shortfall, then renew.
737	 *
738	 * The card NEVER pays the invoice directly. It credits the wallet with exactly
739	 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
740	 * wallet — identical to how checkout splits a purchase. That ordering is what
741	 * makes a crash safe in both directions: money captured but not yet applied sits
742	 * in the customer's wallet as credit (visible, spendable, refundable), and a
743	 * renewal can never be granted without a matching debit.
744	 *
745	 * TWO idempotency guards ride on every attempt:
746	 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
747	 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
748	 *    and "we recorded it" replays instead of charging again.
749	 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
750	 *    identical request for 24h, which covers two overlapping sweeps of the SAME
751	 *    scheduled attempt. The attempt and amount are in the key because a genuine
752	 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
753	 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
754	 *
755	 * And the credit itself is guarded by the UNIQUE index on
756	 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
757	 *
758	 * @returns true when the term was actually extended.
759	 */
760	async function attemptCardRenewal(opts: {
761	  server: DueServer;
762	  charge: RenewalCharge;
763	  cardCents: number;
764	  newExpiry: Date;
765	  now: Date;
766	  cfg: DunningConfig;
767	  /** Destination country the VAT was charged for; passed through to the invoice. */
768	  taxCountry?: string;
769	}): Promise<boolean> {
770	  const { server, charge, cardCents, newExpiry, now, cfg, taxCountry } = opts;
771	  const user = server.user;
772	  const periodStart = server.expiresAt!;
773	  const marker = renewalChargeMarker(server.id, periodStart);
774	  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
775	  const cardLabel = savedCardLabel(user) ?? "your saved card";
776	
777	  const result = await chargeSavedCardOffSession({
778	    user,
779	    amountCents: cardCents,
780	    description: `Renewal: ${charge.label} (${server.hostname})`,
781	    marker,
782	    idempotencyKey,
783	    metadata: {
784	      nxeonServerId: server.id,
785	      nxeonPeriodStart: periodStart.toISOString(),
786	      nxeonKind: "renewal",
787	    },
788	  });
789	
790	  if (result.ok) {
791	    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
792	    // an older amount and the ledger must match the bank, not our intent.
793	    const credited = await creditOffSessionCharge({
794	      userId: server.userId,
795	      amountCents: result.amountCents,
796	      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
797	      paymentIntentId: result.paymentIntentId,
798	      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
799	      // the whole renewal, and a second document for the card portion would
800	      // double-count the same revenue.
801	    });
802	    const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry });
803	
804	    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
805	    // returns false on the P2002 that means "already credited", so a replayed
806	    // capture cannot email the same customer a second receipt for one charge.
807	    if (credited) {
808	      await mail(
809	        user.email,
810	        user.id,
811	        emails.paymentReceipt(
812	          fmtUsd(result.amountCents),
813	          `${charge.label} — ${server.hostname}`,
814	          user.cardLast4 ?? "",
815	        ),
816	        // ACCOUNT tier — a receipt is the one mail from this sweep a customer may
817	        // legitimately opt out of. Everything else here is CRITICAL by default.
818	        "receipt",
819	      );
820	    }
821	
