  // the WHOLE pre-tax subtotal — plan plus every add-on line — because "50% off
  // your next renewal" is a single-event promise about the bill, not about one
  // line on it. Clamped 0..100 so a corrupt/out-of-range stored value can never
  // produce a negative charge or mint a discount beyond what was ever written
  // (claimRetentionOffer only ever writes 50). Applied BEFORE tax, matching
  // every other discount on this platform (coupons, promos) — the customer is
  // taxed on what they actually pay, not on the list price.
  const pendingDiscountPercent = Math.max(0, Math.min(100, server.pendingRenewalDiscountPercent ?? 0));
  const retentionDiscountCents =
    pendingDiscountPercent > 0 ? Math.round((preRetentionNetCents * pendingDiscountPercent) / 100) : 0;
  const netCents = preRetentionNetCents - retentionDiscountCents;
  // VAT/GST on the pre-tax subtotal. Default rate 0 keeps `totalCents === netCents`
  // for every caller that does not pass the owner's rate (Finding 1).
  const taxRatePercent =
    Number.isFinite(prices.taxRatePercent) && (prices.taxRatePercent ?? 0) > 0 ? prices.taxRatePercent! : 0;
  const taxCents = Math.round((netCents * taxRatePercent) / 100);
  return {
    months,
    netCents,
    taxCents,
    taxRatePercent,
    totalCents: netCents + taxCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    backupCents,
    backupMonthlyCents,
    retentionDiscountCents,
    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
  };
}

