// ---------- Retention offer (STAY50) ----------
//
// Shown as an interstitial the instant a customer clicks EITHER cancel path
// above ("Turn off auto-renew" / "Terminate now") in CancelService.tsx, BEFORE
// `cancelService` itself ever runs — "Wait — here's 50% off your next
// renewal. Stay and save?" with a real, undeceptive choice: accept it (this
// module), or continue with the cancellation exactly as today.
//
// THIS IS NOT THE SAME MECHANISM AS THE CHECKOUT COUPON PATH
// (lib/order.ts / lib/coupon-order.ts). There is no new order here for that
// code to fire on — the discount has to land on a FUTURE RENEWAL CHARGE
// against an EXISTING server, so it rides `Server.pendingRenewalDiscountPercent`
// (see that field's doc comment in prisma/schema.prisma and
// `PricedServer.pendingRenewalDiscountPercent` in lib/renewal-charge.ts for how
// `renewalCharge` reads and the worker/`renewNow` clear it). The real Coupon /
// CouponRedemption engine is still reused here, but ONLY for what it is
// already good at: proving "has this account ever redeemed STAY50 before" —
// the exact same `@@unique([couponId, userId])` constraint that makes every
// other one-per-person coupon on this platform enforceable, applied here as a
// simple atomic claim rather than a checkout-time price adjustment.
const RETENTION_COUPON_CODE = "STAY50";
const RETENTION_DISCOUNT_PERCENT = 50;

/**
 * Has this ACCOUNT already spent its one lifetime "stay and save" offer?
 *
 * Scoped to the ACCOUNT, not the server that triggered it: the coupon engine's
 * uniqueness is `(couponId, userId)`, not `(couponId, userId, serverId)` — there
 * is no server dimension to redeem against. So redeeming STAY50 while cancelling
 * one server spends the account's only redemption; cancelling a DIFFERENT
 * server later does not offer it again. This is a deliberate choice, not a
 * limitation of the schema: without it, a customer with three servers could
 * cancel-then-restore each one in turn and collect three separate 50%-off
 * renewals from what is supposed to be a single save-the-account nudge. One
 * offer per account, ever, mirrors how every other first-time/one-per-person
 * coupon on this platform already works.
 */
async function hasRetentionOfferAvailable(userId: string): Promise<{ coupon: { id: string; active: boolean; maxRedemptions: number | null; timesRedeemed: number } } | null> {
  const coupon = await db.coupon.findUnique({
    where: { code: RETENTION_COUPON_CODE },
    select: { id: true, active: true, maxRedemptions: true, timesRedeemed: true },
  });
  if (!coupon || !coupon.active) return null;
  const used = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: coupon.id, userId } },
    select: { id: true },
  });
  if (used) return null;
  return { coupon };
}

/**
 * Server-side eligibility check for the cancel-flow interstitial — read by the
 * server component that renders `CancelService` so the "stay and save" popup
 * is only ever offered when it could actually do something: the master
 * setting is on, this server has a real billing term to discount, it doesn't
 * already carry a pending discount, and this account hasn't used STAY50
 * before. Never trust a client-only version of this check for something that
 * decides whether a real discount can be claimed.
 */
export async function retentionOfferEligible(serverId: string): Promise<boolean> {
  const { user, server } = await ownedServer(serverId);
  if (!(await getSettingBool("retention_offer_enabled", true))) return false;
  if (server.isFree || !server.expiresAt) return false;
  if (server.pendingRenewalDiscountPercent != null) return false;
  return (await hasRetentionOfferAvailable(user.id)) !== null;
}

/**
 * Accept the retention offer: claim STAY50 (one per account, ever) and stamp
 * the discount onto THIS server for its very next renewal only.
 *
 * Deliberately does NOT itself cancel, un-cancel or terminate anything beyond
 * turning auto-renew back on (accepting the offer is, definitionally, a
 * decision to keep renewing) — the caller (CancelService.tsx) is responsible
 * for not proceeding with whichever cancellation the customer was about to
 * make. That keeps this function's blast radius exactly "one server's next
 * bill", the same discipline `claimOrderCoupon` keeps for a checkout coupon.
 */
export async function claimRetentionOffer(serverId: string): Promise<{ error?: string; ok?: boolean }> {
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);

  if (!(await getSettingBool("retention_offer_enabled", true))) {
    return { error: "This offer isn't available right now." };
  }
  if (server.isFree || !server.expiresAt) {
    return { error: "This server has no billing term to discount." };
  }
  if (server.pendingRenewalDiscountPercent != null) {
    return { error: "A discount is already pending on this server's next renewal." };
  }

  const available = await hasRetentionOfferAvailable(user.id);
  if (!available) {
    return { error: "You've already used this offer, or it isn't available right now." };
  }
  const { coupon } = available;

  try {
    await db.$transaction(async (tx) => {
      // Same atomic-claim shape as claimOrderCoupon (lib/order.ts): a conditional
      // increment on the coupon's own counter, then the unique-constrained
      // insert. Two concurrent claims (two tabs) can't both win — the loser's
      // insert throws P2002 and rolls the increment back with it.
      const claim = await tx.coupon.updateMany({
        where:
          coupon.maxRedemptions === null
            ? { id: coupon.id, active: true }
            : { id: coupon.id, active: true, timesRedeemed: { lt: coupon.maxRedemptions } },
        data: { timesRedeemed: { increment: 1 } },
      });
      if (claim.count !== 1) throw new Error("RETENTION_OFFER_EXHAUSTED");
      try {
        await tx.couponRedemption.create({
          data: { couponId: coupon.id, userId: user.id, amountCents: 0, context: "retention" },
        });
      } catch {
        // Unique violation on (coupon, user): already claimed, most likely a
        // race with another tab. Throwing rolls back the increment above.
        throw new Error("RETENTION_OFFER_ALREADY_USED");
      }
      await tx.server.update({
        where: { id: server.id },
        data: { pendingRenewalDiscountPercent: RETENTION_DISCOUNT_PERCENT, autoRenew: true },
      });
      await tx.auditLog.create({
        data: { userId: user.id, action: "server.retention_offer_claimed", detail: serverId },
      });
    });
  } catch (e) {
    if (e instanceof Error && e.message === "RETENTION_OFFER_ALREADY_USED") {
      return { error: "You've already used this offer once." };
    }
    if (e instanceof Error && e.message === "RETENTION_OFFER_EXHAUSTED") {
      return { error: "This offer is no longer available." };
    }
    throw e;
  }

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

