"use client";

import { useState, useTransition } from "react";
import { createPortal } from "react-dom";
import { claimRetentionOffer } from "@/lib/actions-server-lifecycle";

/**
 * "Wait — before you go" interstitial shown the instant a customer clicks
 * EITHER cancel path in CancelService.tsx (turn off auto-renew, or terminate
 * immediately), BEFORE the cancellation itself runs.
 *
 * A real, undeceptive choice — not a dark pattern that traps them:
 *   - "Stay and save 50%" claims the discount (lib/actions-server-lifecycle.ts
 *     claimRetentionOffer) and does NOT cancel anything.
 *   - "Continue cancelling" closes this and runs the ORIGINAL cancellation the
 *     customer asked for, exactly as if this modal had never appeared.
 *
 * Built like SettleBalanceModal.tsx — the same portaled `fixed inset-0`
 * dialog over `document.body`, for the same reason: an ancestor's transform
 * (this renders inside the server detail page's cards) would otherwise become
 * the containing block for a `fixed` element and clip it.
 */
export function RetentionOfferModal({
  serverId,
  hostname,
  onAccepted,
  onContinue,
  onClose,
}: {
  serverId: string;
  hostname: string;
  /** Called after the discount is successfully claimed — does NOT cancel. */
  onAccepted: () => void;
  /** Called when the customer chooses to go ahead with the original cancellation anyway. */
  onContinue: () => void;
  /** Called when the dialog is dismissed with neither button (Esc / backdrop / ✕). */
  onClose: () => void;
}) {
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  const accept = () => {
    setError(null);
    startTransition(async () => {
      const res = await claimRetentionOffer(serverId);
      if (res?.error) {
        setError(res.error);
        return;
      }
      onAccepted();
    });
  };

  return createPortal(
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
      role="dialog"
      aria-modal="true"
      aria-label="Special offer before you cancel"
    >
      <div className="relative my-auto w-full max-w-md rounded-2xl border border-white/10 bg-navy-950 p-5 shadow-2xl">
        <div className="flex items-center justify-between pb-4">
          <p className="text-sm font-semibold text-slate-100">Wait — before you go</p>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            disabled={pending}
            className="rounded-lg px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-white"
          >
            ✕
          </button>
        </div>

        <div className="space-y-4">
          <p className="text-[13px] leading-[1.5] text-slate-300">
            Here&apos;s <span className="font-semibold text-emerald-300">50% off</span> the next renewal on{" "}
            <span className="font-semibold text-slate-100">{hostname}</span> — a one-time thank-you for staying.
            Applied automatically; nothing is cancelled.
          </p>

          {error && (
            <p className="rounded-lg border border-red-500/25 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>
          )}

          <button type="button" onClick={accept} disabled={pending} className="btn-deploy w-full py-3 text-sm">
            {pending ? "Applying…" : "Stay and save 50%"}
            {!pending && <span className="dep-arrow">→</span>}
          </button>
          <button
            type="button"
            onClick={onContinue}
            disabled={pending}
            className="w-full py-1.5 text-center text-xs text-slate-500 transition hover:text-slate-300"
          >
            No thanks, continue cancelling
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

