  paypalClientId: string | null;
  isFirstTimeCustomer: boolean;
  exitIntentEnabled: boolean;
}) {
  const { o, set, chooseService, chooseGame, toggleAddon, cat, sections, game } = useOrder();
  const money = useMoney();
  const [i, setI] = useState(0);

  /* ── Exit-intent 25%-off popup (first-time customers only) ──────────────
   *
   * Shown ONCE per visit — `exitIntentState` starts "idle" and only ever
   * moves forward (idle -> shown -> claimed|dismissed), so a second
   * mouseleave-to-top after the first can never re-open it. Deliberately
   * component state, not localStorage/a cookie: this is a per-visit nudge,
   * not a claim record — the real one-time enforcement lives server-side
   * (EXIT25's `firstTimeOnly` + the per-account/per-IP CouponRedemption
   * uniques), so persisting "already showed the popup" across a reload would
   * only cost a legitimate second look on a refreshed tab, never prevent abuse.
   *
   * Only armed on the PRICING step ("configure" — VPS "Choose your plan" /
   * game "Size your server", both keyed "configure" in components/nx/order.tsx)
   * of a VPS or game order, and only for a signed-in first-time customer while
   * the admin switch is on. The classic exit-intent signal: the mouse leaving
   * the whole viewport toward the browser chrome above it.
   */
  const [exitIntent, setExitIntent] = useState<"idle" | "shown" | "claimed" | "dismissed">("idle");
  const onPricingStep = sections[i]?.key === "configure" && (o.service === "vps" || o.service === "game");
  useEffect(() => {
    if (!isFirstTimeCustomer || !exitIntentEnabled || exitIntent !== "idle" || !onPricingStep) return;
    function handleLeave(e: MouseEvent) {
      if (e.clientY > 0) return;
      setExitIntent("shown");
    }
    document.addEventListener("mouseleave", handleLeave);
    return () => document.removeEventListener("mouseleave", handleLeave);
  }, [isFirstTimeCustomer, exitIntentEnabled, exitIntent, onPricingStep]);

  // Auto-dismiss the "applied" confirmation toast after a few seconds — it
  // does not clear `o.couponCode`, so the discount stays applied regardless.
  useEffect(() => {
    if (exitIntent !== "claimed") return;
    const t = setTimeout(() => setExitIntent("dismissed"), 6000);
