import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { renewalCharge, type PricedServer, type RenewalPrices } from "../lib/renewal-charge.ts";

/**
 * The cancel-plan retention offer ("stay and save 50% off your next renewal",
 * lib/actions-server-lifecycle.ts claimRetentionOffer + Server.
 * pendingRenewalDiscountPercent). Three guarantees, matching the shape of
 * test/money-core-guards.test.ts: arithmetic asserted directly against the
 * pure `renewalCharge` formula, and the parts that live inside "use server"
 * files (the clearing writes, the one-per-account claim) asserted against the
 * file's own CODE, comments stripped first so a fix's own explanatory comment
 * can never be mistaken for the guarantee it describes.
 *
 * (a) the discount actually reduces the very next renewal charge by 50%
 * (b) it does NOT apply to the renewal after that
 * (c) an account that already redeemed it once cannot get it offered/applied again
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

function fn(src: string, declaration: string): string {
  const start = src.indexOf(declaration);
  assert.notEqual(start, -1, `${declaration} not found`);
  const rest = src.slice(start + declaration.length);
  const next = rest.search(/\nexport (async )?(function|const|type|class)/);
  const body = next === -1 ? rest : rest.slice(0, next);
  assert.ok(body.length > 0, `${declaration} produced an empty body`);
  return body;
}

const LIFECYCLE = code("../lib/actions-server-lifecycle.ts");
const BILLING = code("../worker/billing.ts");
const ACTIONS = code("../lib/actions.ts");

/* ------------------------------------------------------------------ *
 * (a) The discount actually halves the very next renewal charge
 * ------------------------------------------------------------------ */

const BASE_PRICES: RenewalPrices = {
  ipMonthlyCents: 0,
  extraDiskPerGbCents: 0,
  backupPlusCents: 0,
  annualDiscountPct: 0,
};

function pricedServer(overrides: Partial<PricedServer> = {}): PricedServer {
  return {
    termMonths: 1,
    extraDiskGB: 0,
    plan: { name: "Starter", priceCents: 1000 },
    gamePlan: null,
    dedicatedIp: null,
    wantsDedicatedIp: false,
    backupTier: "FREE" as PricedServer["backupTier"],
    ...overrides,
  };
}

test("a 50% pending retention discount halves the renewal total, exactly", () => {
  const full = renewalCharge(pricedServer(), BASE_PRICES);
  const discounted = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 50 }), BASE_PRICES);

  assert.equal(full.totalCents, 1000, "sanity: full price is $10.00");
  assert.equal(discounted.totalCents, 500, "50% off $10.00 is $5.00");
  assert.equal(discounted.retentionDiscountCents, 500, "the discount line reports exactly what was shaved off");
  assert.equal(discounted.netCents + discounted.retentionDiscountCents, full.netCents,
    "the pre-discount subtotal must equal the ordinary full-price subtotal, so the invoice's base line + the discount line always reconcile");
});

test("the discount applies to the WHOLE renewal — plan plus every add-on line — not just the plan", () => {
  const withAddons = pricedServer({
    extraDiskGB: 20,
    dedicatedIp: {},
    wantsDedicatedIp: true,
  });
  const prices: RenewalPrices = { ipMonthlyCents: 200, extraDiskPerGbCents: 10, backupPlusCents: 0, annualDiscountPct: 0 };
  const full = renewalCharge(withAddons, prices);
  const discounted = renewalCharge({ ...withAddons, pendingRenewalDiscountPercent: 50 }, prices);

  // plan 1000 + ip 200 + disk (20 * 10) 200 = 1400 full; half of that is 700.
  assert.equal(full.totalCents, 1400);
  assert.equal(discounted.totalCents, 700);
  assert.equal(discounted.retentionDiscountCents, 700);
});

test("the discount is applied BEFORE tax, same as every other discount on this platform", () => {
  const prices: RenewalPrices = { ...BASE_PRICES, taxRatePercent: 10 };
  const discounted = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 50 }), prices);
  // netCents 500 (50% of 1000), tax is 10% of the DISCOUNTED net, not the list price.
  assert.equal(discounted.netCents, 500);
  assert.equal(discounted.taxCents, 50, "tax must be computed on what the customer actually pays, not the pre-discount list price");
  assert.equal(discounted.totalCents, 550);
});

test("a corrupt/out-of-range stored percent is clamped, never a negative charge or a >100% gift", () => {
  const over = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: 150 }), BASE_PRICES);
  assert.equal(over.totalCents, 0, "clamped to 100%, not allowed to go negative");

  const negative = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: -20 }), BASE_PRICES);
  assert.equal(negative.totalCents, 1000, "a negative stored value must never mean a SURCHARGE — treated as no discount");
});

/* ------------------------------------------------------------------ *
 * (b) It does NOT apply to the renewal after that
 * ------------------------------------------------------------------ */

test("with no pending discount (the post-clear state) the renewal is full price", () => {
  const cleared = renewalCharge(pricedServer({ pendingRenewalDiscountPercent: null }), BASE_PRICES);
  assert.equal(cleared.totalCents, 1000);
  assert.equal(cleared.retentionDiscountCents, 0, "nothing to report once the field is cleared");
});

test("worker/billing.ts commitRenewal clears pendingRenewalDiscountPercent in the SAME CAS-guarded write that advances the period", () => {
  const commitRenewal = fn(BILLING, "async function commitRenewal(");
  // Must be part of the `data` object passed to the compare-and-swap
  // `tx.server.updateMany` — the same write that advances `expiresAt` — so a
  // losing/replayed pass (which matches zero rows) clears nothing, and a
  // winning pass can never advance the period while leaving the discount
  // armed for the period after it.
  const updateManyBlock = commitRenewal.slice(
    commitRenewal.indexOf("tx.server.updateMany({"),
    commitRenewal.indexOf("if (advanced.count === 0)"),
  );
  assert.match(updateManyBlock, /where:\s*\{\s*id:\s*server\.id,\s*expiresAt:\s*server\.expiresAt\s*\}/,
    "the clear must ride the same expiresAt compare-and-swap as the renewal itself");
  assert.match(updateManyBlock, /pendingRenewalDiscountPercent:\s*null/,
    "commitRenewal must clear the discount unconditionally on every successful renewal");
});

test("lib/actions.ts renewNow (manual 'Renew now') ALSO honors and then clears the pending discount", () => {
  const renewNow = fn(ACTIONS, "export async function renewNow(");
  assert.match(renewNow, /pendingRenewalDiscountPercent:\s*server\.pendingRenewalDiscountPercent/,
    "a manual renewal is still 'the very next renewal' the offer was promised for — it must read the field renewalCharge needs");
  const updateManyBlock = renewNow.slice(
    renewNow.indexOf("tx.server.updateMany({"),
    renewNow.indexOf("if (adv.count === 0)"),
  );
  assert.match(updateManyBlock, /where:\s*\{\s*id:\s*serverId,\s*expiresAt:\s*E\s*\}/,
    "the clear must ride the same expiresAt compare-and-swap as the manual renewal itself");
  assert.match(updateManyBlock, /pendingRenewalDiscountPercent:\s*null/,
    "renewNow must clear the discount unconditionally on every successful manual renewal too — otherwise clicking Renew now instead of waiting for the sweep would let the discount silently survive into a second period");
});

/* ------------------------------------------------------------------ *
 * (c) An account that already redeemed STAY50 cannot be offered or claim it again
 * ------------------------------------------------------------------ */

test("eligibility is denied once a CouponRedemption already exists for (STAY50, this user)", () => {
  const hasOffer = fn(LIFECYCLE, "async function hasRetentionOfferAvailable(");
  assert.match(hasOffer, /couponRedemption\.findUnique\(\{\s*where:\s*\{\s*couponId_userId:/,
    "must check the real per-account uniqueness the coupon engine already enforces everywhere else");
  assert.match(hasOffer, /if \(used\) return null;/, "a prior redemption must refuse eligibility, not just warn");
});

test("retentionOfferEligible (read by the cancel-flow UI) delegates to the same one-per-account check", () => {
  const eligible = fn(LIFECYCLE, "export async function retentionOfferEligible(");
  assert.match(eligible, /hasRetentionOfferAvailable\(user\.id\)/,
    "the UI-facing eligibility check must not duplicate or diverge from the claim-time check");
});

test("claimRetentionOffer's insert is guarded by the SAME atomic-claim shape as claimOrderCoupon: conditional increment then a unique-constrained insert", () => {
  const claim = fn(LIFECYCLE, "export async function claimRetentionOffer(");
  // The conditional increment on the coupon's own counter — the thing that
  // stops two concurrent claims (two tabs) from both winning even before the
  // per-user unique is reached.
  assert.match(claim, /tx\.coupon\.updateMany\(\{/);
  assert.match(claim, /data:\s*\{\s*timesRedeemed:\s*\{\s*increment:\s*1\s*\}\s*\}/);
  assert.match(claim, /if \(claim\.count !== 1\) throw new Error\("RETENTION_OFFER_EXHAUSTED"\);/);
  // The insert that actually trips the per-account unique on a second attempt,
  // and rolls the increment above back with it via the throw.
  assert.match(claim, /tx\.couponRedemption\.create\(\{/);
  assert.match(claim, /throw new Error\("RETENTION_OFFER_ALREADY_USED"\);/);
  // Re-checked BEFORE the transaction too, so the common case (already used)
  // fails fast with a clean error instead of relying on the DB round-trip alone.
  assert.match(claim, /const available = await hasRetentionOfferAvailable\(user\.id\);/);
});

test("claiming is scoped to the ACCOUNT, not the server that triggered it — one offer, ever, across every server", () => {
  // The redemption insert carries userId only — no serverId — so the
  // @@unique([couponId, userId]) constraint blocks a second claim from the
  // SAME account regardless of which server it cancels next.
  const claim = fn(LIFECYCLE, "export async function claimRetentionOffer(");
  const createBlock = claim.slice(claim.indexOf("tx.couponRedemption.create({"), claim.indexOf("tx.couponRedemption.create({") + 220);
  assert.match(createBlock, /couponId:\s*coupon\.id,\s*userId:\s*user\.id/);
  assert.doesNotMatch(createBlock, /serverId/, "redemption must not be scoped per-server, or the same account could farm one 50%-off per server");
});

