// Throwaway browser check for the exit-intent 25%-off popup (Feature 1),
// run against the STAGING environment only. Registers a fresh first-time
// test account, reaches the deploy wizard's VPS pricing step, fires the
// exit-intent signal, confirms the modal appears exactly once, claims the
// discount, and confirms the coupon field / applied price actually changed.
import { chromium } from "playwright";

const BASE = process.env.BASE_URL || "http://127.0.0.1:8080";
const stamp = Date.now();
const email = `exit-intent-test-${stamp}@example.com`;
const password = "TestPass123!";

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  page.on("console", (m) => { if (m.type() === "error") console.log("[console.error]", m.text()); });

  console.log("==> Registering fresh test account:", email);
  await page.goto(BASE + "/register", { waitUntil: "networkidle" });
  await page.fill('input[name="name"]', "Exit Intent Test");
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button[type="submit"]');
  await page.waitForURL(/dashboard/, { timeout: 20000 }).catch(async () => {
    console.log("==> Register did not auto-redirect to dashboard, current URL:", page.url());
  });
  console.log("==> Post-register URL:", page.url());

  console.log("==> Navigating to deploy wizard");
  await page.goto(BASE + "/dashboard/deploy", { waitUntil: "networkidle" });

  // Pick VPS if a service tile step is shown first.
  const vpsTile = page.locator('text="VPS Hosting"').first();
  if (await vpsTile.count()) {
    await vpsTile.click().catch(() => {});
  } else {
    // Fallback: any tile containing "VPS"
    const tile = page.locator("text=/VPS/i").first();
    if (await tile.count()) await tile.click().catch(() => {});
  }
  await page.waitForTimeout(800);

  // Confirm we're on/near the pricing ("Choose your plan") step.
  const pricingHeading = page.locator("text=/Choose your plan/i").first();
  const onPricing = await pricingHeading.count();
  console.log("==> 'Choose your plan' heading present:", onPricing > 0);

  console.log("==> Firing exit-intent (document mouseleave, clientY<=0)");
  await page.evaluate(() => {
    document.dispatchEvent(new MouseEvent("mouseleave", { clientY: -5, clientX: 500, bubbles: false, cancelable: true }));
  });
  await page.waitForTimeout(400);

  const modal = page.locator('[aria-label="Limited-time discount"]');
  const modalVisibleOnce = await modal.isVisible().catch(() => false);
  console.log("==> Exit-intent modal visible after first mouseleave:", modalVisibleOnce);

  // Fire it again — must NOT reopen (shown-once-per-visit).
  await page.evaluate(() => {
    document.dispatchEvent(new MouseEvent("mouseleave", { clientY: -5, clientX: 500, bubbles: false, cancelable: true }));
  });
  await page.waitForTimeout(300);
  const stillJustOne = await modal.isVisible().catch(() => false);
  console.log("==> Modal still shown correctly after 2nd mouseleave (should be unaffected by re-trigger while already open):", stillJustOne);

  if (modalVisibleOnce) {
    console.log("==> Clicking 'Claim 25% off'");
    await page.locator('button:has-text("Claim 25% off")').click();
    await page.waitForTimeout(1500);

    const couponInput = page.locator('input[placeholder="Promo code"]');
    const couponValue = await couponInput.inputValue().catch(() => null);
    console.log("==> Promo code field value after claim:", couponValue);

    const toast = page.locator("text=/25% off applied/i");
    console.log("==> Confirmation toast visible:", await toast.isVisible().catch(() => false));

    // Reopen? Should NOT reopen on a third mouseleave (state moved to "claimed").
    await page.evaluate(() => {
      document.dispatchEvent(new MouseEvent("mouseleave", { clientY: -5, clientX: 500, bubbles: false, cancelable: true }));
    });
    await page.waitForTimeout(300);
    const reopened = await modal.isVisible().catch(() => false);
    console.log("==> Modal reopened after claim (should be false):", reopened);
  }

  await page.screenshot({ path: "/tmp/exit-intent-result.png", fullPage: false });
  await browser.close();
};

run().catch((e) => { console.error(e); process.exit(1); });

